  s = s.replace(/<svg[\s\S]*?<\/svg>/gi, ' ');
  s = s.replace(/<head[\s\S]*?<\/head>/gi, ' ');

  // Tags entfernen
  s = s.replace(/<[^>]+>/g, ' ');

  // Entities / Whitespaces
  s = decode(s);
  s = s.replace(/\s+/g, ' ').trim();

  return s;
}

function cleanEmail(e) {
  return String(e || '')
    .replace(/^mailto:/i, '')
    .replace(/[?].*$/, '')
    .replace(/[<>"'(),;]+$/g, '')
    .trim();
}

function getHost(url) {
  try {
    return new URL(url).hostname.replace(/^www\./, '').toLowerCase();
  } catch (e) {
    return '';
  }
}

function toAbsoluteUrl(baseUrl, maybeRelative) {
  try {
    return new URL(maybeRelative, baseUrl).href;
  } catch (e) {
    return '';
  }
}

function isBad(email) {
  const l = String(email || '').toLowerCase();
  if (!l.includes('@') || l.length > 100) return true;

  if (badDomains.some(d => l.includes(d))) return true;
  if (['.png', '.jpg', '.jpeg', '.js', '.css', '.svg', '.gif', '.woff', '.map', '.webp'].some(x => l.endsWith(x))) return true;

  const domain = (l.split('@')[1] || '');
  if (!domain) return true;
  if (domain.split('.').length < 2) return true;

  return false;
}

function scoreEmail(email, host) {
  const l = email.toLowerCase();
  let s = 0;

  for (let i = 0; i < prio.length; i++) {
    if (l.startsWith(prio[i])) {
      s += (prio.length - i) * 100;
      break;
    }
  }

  const domain = (l.split('@')[1] || '').replace(/^www\./, '');
  if (host && domain === host) s += 80;
  if (host && domain.endsWith('.' + host)) s += 60;

  if (l.startsWith('datenschutz@') || l.startsWith('privacy@')) s -= 20;

  return s;
}

function extractEmailsFromText(text) {
  if (!text) return [];

  const t = decode(text);

  const found = new Set();

  // 1) Standard-Mailadressen
  for (const m of t.matchAll(emailRegex)) {
    const e = cleanEmail(m[0]);
    if (e) found.add(e);
  }

  // 2) mailto:
  for (const m of t.matchAll(/mailto:([^\s"'<>?]+)/gi)) {
    const e = cleanEmail(m[1]);
    if (e) found.add(e);
  }

  // 3) Obfuskationen wie kontakt(at)di-w.de / kontakt [at] di-w.de / kontakt(at) di-w.de
  const obfPatterns = [
    /([a-zA-Z0-9._%+\-]+)\s*(?:\(|\[)?at(?:\)|\])?\s*([a-zA-Z0-9.\-]+)\s*(?:\(|\[)?dot(?:\)|\])?\s*([a-zA-Z]{2,})/gi,
    /([a-zA-Z0-9._%+\-]+)\s*\(\s*at\s*\)\s*([a-zA-Z0-9.\-]+)\s*\.\s*([a-zA-Z]{2,})/gi,
    /([a-zA-Z0-9._%+\-]+)\s*\[\s*at\s*\]\s*([a-zA-Z0-9.\-]+)\s*\[\s*dot\s*\]\s*([a-zA-Z]{2,})/gi,
  ];

  for (const re of obfPatterns) {
    for (const m of t.matchAll(re)) {
      const e = `${m[1]}@${m[2]}.${m[3]}`;
      found.add(cleanEmail(e));
    }
  }

  return [...found].filter(Boolean);
}

function bestEmailFromHtml(html, host) {
  if (!html) return '';

  const text = htmlToText(html);
  const candidates = extractEmailsFromText(text)
    .filter(e => !isBad(e));

  if (!candidates.length) return '';

  candidates.sort((a, b) => scoreEmail(b, host) - scoreEmail(a, host));
  return candidates[0] || '';
}

function extractCandidateLinks(html, baseUrl) {
  if (!html || !baseUrl) return [];

  const text = decode(String(html));
  const hrefs = [...text.matchAll(/href\s*=\s*["']([^"']+)["']/gi)].map(m => m[1]);

  const keywords = [
    'impressum',
    'kontakt',
    'contact',
    'ueber-uns',
    'über-uns',
    'about',
    'datenschutz',
  ];

  const out = [];
  for (const href of hrefs) {
    const lower = href.toLowerCase();
    if (keywords.some(k => lower.includes(k))) {
      const abs = toAbsoluteUrl(baseUrl, href);
      if (abs) out.push(abs);
    }
  }

  return [...new Set(out)];
}

function guessCommonPages(baseUrl) {
  const paths = [
    '/impressum',
    '/impressum/',
    '/kontakt',
    '/kontakt/',
    '/contact',
    '/contact/',
    '/about',
    '/about/',
    '/ueber-uns',
    '/ueber-uns/',
    '/datenschutz',
    '/datenschutz/',
  ];

  const out = [];
  for (const p of paths) {
    try {
      out.push(new URL(p, baseUrl).href);
    } catch (e) {}
  }

  return [...new Set(out)];
}

async function fetchHtml(url) {
  if (!url) return '';
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url,
      headers: {
        'User-Agent': 'Mozilla/5.0',
        'Accept': 'text/html,application/xhtml+xml',
      },
      timeout: 15000,
      json: false,
    });
    return typeof res === 'string' ? res : String(res || '');
  } catch (e) {
    return '';
  }
}

async function resolveEmailFromSite(initialHtml, baseUrl) {
  const host = getHost(baseUrl);

  // 1) Direkt im HTML
  let email = bestEmailFromHtml(initialHtml, host);
  if (email) return email;

  // 2) Kontakt-/Impressumslinks aus dem HTML
  const candidateUrls = [
    ...extractCandidateLinks(initialHtml, baseUrl),
    ...guessCommonPages(baseUrl),
  ];

  for (const url of [...new Set(candidateUrls)].slice(0, 8)) {
    const subHtml = await fetchHtml.call(this, url);
    email = bestEmailFromHtml(subHtml, getHost(url));
    if (email) return email;
  }

  return '';
}

function getByNodeIndex(nodeName, i) {
  try {
    const arr = $items(nodeName);
    return arr[i]?.json || {};
  } catch (e) {
    return {};
  }
}

function pickPrice(i, current, brave) {
  const direct = current.preis ?? current.price ?? brave.preis ?? brave.price;
  if (direct !== undefined && direct !== null && String(direct).trim() !== '') return direct;

  for (const nodeName of priceSourceNodes) {
    const x = getByNodeIndex(nodeName, i);
    const candidate = x.preis ?? x.price ?? x.cost ?? x.gebuehr ?? x.gebühren;
    if (candidate !== undefined && candidate !== null && String(candidate).trim() !== '') {
      return candidate;
    }
  }

  return '';
}

const result = [];

for (let i = 0; i < items.length; i++) {
  const current = items[i]?.json || {};
  const brave = braveItems[i]?.json || {};
  const picked = brave.picked || {};

  const name =
    current.name ||
    brave.name ||
    picked.title ||
    '';

  const website =
    current.website ||
    current.url ||
    current.impressum_url ||
    brave.website ||
    picked.url ||
    '';

  const preis = pickPrice(i, current, brave);

  const html =
    current.impressum_html ||
    current.data ||
    current.body ||
    await fetchHtml.call(this, website);

  const email = await resolveEmailFromSite.call(this, html, website);

  result.push({
    json: {
      name,
      preis,
      website,
      email,
    },
  });
}

return result;
